#include "KS/SRC/ks/FEPanel_shared.h"

class PanelAnimKeyframe
{
public:
	float idx;
	vector3d translation;
	vector3d euler;
	vector3d scale;
	stringx event;
	float vis;
};

class PanelAnim
{
public:
	stringx name;
	stringx properties;
	PanelAnim* parent;
	matrix4x4 matrix;
	unsigned numkeyframes;
	PanelAnimKeyframe* keyframes;
	PanelAnim* children;
	PanelAnim* next;

	virtual ~PanelAnim();
	virtual int Kind() const = 0;
	bool GetEvent(float start_time, float end_time, stringx& event);
};

